const boot=require('/tmp/stage5-vm.cjs'),fs=require('fs');
const squads={solo:[],balanced:['shooter','healer','tank','sniper'],damage:['shooter','brawler','sniper','engineer'],support:['healer','tank','trapper','bard']};
const rows=[];
for(const mode of (process.env.QA_MODES||'cataclysm-1-0-major,cataclysm-100-lab').split(','))for(const night of (process.env.QA_NIGHTS||'1,45,85,100').split(',').map(Number))for(const [build,roles] of Object.entries(squads).filter(([b])=>!process.env.QA_BUILDS||process.env.QA_BUILDS.split(',').includes(b))){
 const c=boot(mode),q=c.qa,g=q.get(),p=g.player;q.setSeed(424242);
 g.t=(night-1)*13;g.campaign=c.CATA_MAJOR.newLedger();g.campaign.night=night-1;g.labEconomy=c.CATA_LAB_DIRECTOR.create(990100);g.labEconomy.primeTo(night-1);g.enemies=[];g.shots=[];g.enemyShots=[];g.companionSquad=[];g.companionRanks=Object.fromEntries(Object.keys(c.CATA_FOLLOWERS.roleSpecs).map(k=>[k,0]));g.majorFinalSpawned=false;g.finalDefeated=[];
 const tier=night===1?0:night<60?1:2,late=night===100;
 Object.assign(p,{level:night===1?0:night,damage:1+tier*2+(late?1:0),maxHp:3+tier*9+(late?5:0),hp:3+tier*9+(late?5:0),inv:0,speed:235+tier*45,shotInterval:Math.max(.26,.62-tier*.15),multishot:tier>0?1:0,ricochet:tier,armor:tier*.14,criticalBoost:tier*.1,focus:tier,areaBurst:tier,magnet:tier});
 Object.assign(g.squadStats,{damage:.5+tier*.09,rate:1+tier*.25,count:1,spread:tier>0?1:0,bounce:tier>0?1:0});
 g.world.epoch=Math.floor(g.t/180);g.cityEvents.nextCrane=g.t+90;g.cityEvents.nextCity=g.t+120;g.hazards.spawnTimer=0;g.nextPower=g.t+120;g.survivalPoints=0;g.kills=0;g.fish=0;g.scoreLedger=c.CATA_SCORE.newLedger();g.xp=0;g.pendingUpgrade=false;g.mode='running';
 for(const role of roles)for(let i=0;i<(tier+1);i++)q.summonCompanion(role);
 q.startMajorNight(night);
 let peak={enemies:0,shots:0,enemyShots:0,particles:0},elapsed=0,minHp=p.hp;const start=performance.now();
 for(let frame=0;frame<(late?180:39)*60&&g.mode!=='dead'&&g.mode!=='won';frame++){
   if(g.mode==='upgrade'){q.chooseUpgrade(g.offered[0]);}
   const age=frame/60;let x=0,y=0;
   if(age%7>Number(process.env.QA_HOLD||1.6)){
     let nearest=null,d=Infinity;
     for(const e of g.enemies){const dx=((e.x-p.x+6300)%4200)-2100,dy=e.y-p.y,r=Math.hypot(dx,dy);if(r<d){d=r;nearest={dx,dy};}}
     if(nearest){x=-nearest.dy/Math.max(1,d)-nearest.dx/Math.max(1,d)*(d<180?1:0);y=nearest.dx/Math.max(1,d)-nearest.dy/Math.max(1,d)*(d<180?1:0);}
     else {x=Math.sin(age*.4);y=-.4;}
   }
   q.move(x,y);q.tick(1/60);elapsed+=1/60;minHp=Math.min(minHp,p.hp);
   for(const k of Object.keys(peak))peak[k]=Math.max(peak[k],g[k].length);
 }
 const snap=c.CATACLYSM_DIAGNOSTICS.snapshot();rows.push({mode,night,build,seed:424242,directorSeed:990100,seconds:+elapsed.toFixed(2),stationaryWindow:Number(process.env.QA_HOLD||1.6),outcome:g.mode,hp:+p.hp.toFixed(3),minHp:+minHp.toFixed(3),finalSpawned:g.labFinalSpawned,finalDefeated:g.finalDefeated?.length||0,score:snap.scoring,followers:snap.companions.states,peak,hostSimulationMs:+(performance.now()-start).toFixed(1)});
 fs.writeFileSync((process.env.QA_OUTPUT||'/tmp/stage5-balance.json')+'.partial',JSON.stringify(rows));
 console.error(mode,night,build,g.mode,p.hp.toFixed(2),g.kills,elapsed.toFixed(1));
}
fs.writeFileSync(process.env.QA_OUTPUT||'/tmp/stage5-balance.json',JSON.stringify({method:'Actual unrendered game tick, 60Hz; fixed tier snapshots, earn/apply first offered upgrades; deterministic nearest-threat tangential dodge with stationary 1.6s per 7s. 39s early/mid/late windows, finale up to 180s. Host times are NOT browser FPS.',rows},null,2));

