 g.campaign=c.CATA_MAJOR.newLedger();g.campaign.night=99;g.labEconomy=c.CATA_LAB_DIRECTOR.create(990100);g.labEconomy.primeTo(99);g.t=1287;g.player.inv=0;q.startMajorNight(100);assert.equal(g.player.inv,0);q.releaseLabSpawn();const first=g.enemies[0];assert.equal(first.arrivalUntil,1287.8);q.squadHit(first,1e6);assert.equal(g.finalDefeated.length,1,'first arrival killable without waiting for others');q.finalizeMajorVictory();assert.equal(g.victory,false);
 while(g.labQueue.length){g.t=g.labNextSpawn;q.releaseLabSpawn();}
 assert.equal(g.labFinalSpawned,18);for(const e of [...g.enemies].slice(0,-1))q.squadHit(e,1e6);
 q.finalizeMajorVictory();assert.equal(g.victory,false,'last live enemy gates victory');
 const last=g.enemies[0];g.enemies=[];q.finalizeMajorVictory();assert.equal(g.victory,false,'despawn cannot grant victory');g.enemies=[last];q.squadHit(last,1e6);
 g.player.hp=0;q.finalizeMajorVictory();assert.equal(g.victory,false,'dead player cannot win');g.player.hp=1;
