 assert.equal(q.storage.get(mode.endsWith('lab')?'cataclysm-lab-best':'cataclysm-best'),String(after.total));
 const breakdown=JSON.parse(q.storage.get((mode.endsWith('lab')?'cataclysm-lab-best':'cataclysm-best')+'-breakdown'));assert.equal(breakdown.ruleVersion,c.CATA_SCORE.RULE_VERSION);assert.deepEqual(breakdown.awarded,['night100']);
